-- Attachment metadata table owned by the @commonapp/attachment module
-- (DDL generated by getAttachmentDdl({ tableName: 'attachments', entityColumn: 'entity_id' })).
-- entityId convention: `ticket-<ticketId>` for ticket attachments, `reply-<replyId>` for
-- reply attachments, `draft-<userId>` for uploads staged before a ticket exists.
CREATE TABLE IF NOT EXISTS attachments (
  id TEXT PRIMARY KEY,
  entity_id TEXT NOT NULL,
  name TEXT NOT NULL,
  size INTEGER NOT NULL,
  mime_type TEXT NOT NULL,
  path TEXT NOT NULL DEFAULT '',
  uploaded_at TEXT NOT NULL,
  uploaded_by_id TEXT NOT NULL,
  uploaded_by_name TEXT NOT NULL
);
CREATE INDEX IF NOT EXISTS idx_attachments_entity_id ON attachments(entity_id);

-- Business extension: where the attachment came from (requirements §7.3 / AC-22).
ALTER TABLE attachments ADD COLUMN source TEXT NOT NULL DEFAULT 'upload';
